        artifactId: 'quiz-cards-v1',
        revision: 1,
        checks: [{ id: 'Q-01', kind: 'grounding', passed: false, message: 'bad', affected: ['/cards/0/quote'] }],
        publishable: false
      };
    };
    const requests: CompleteRequest[] = [];
