      repairKitComponent(
        fakeClientFor(rev2, requests),
        source,
        analysis,
        plan,
        { gen: rev1, report: quizValidator(structuredClone(rev1), [source]), attempt },
        'test-live',
        { validate: quizValidator }
      ),
      /REPAIR_ATTEMPT_INVALID/
    );
    assert.equal(requests.length, 0);
  }
  {
