      repairKitComponent(
        fakeClientFor(rev2, requests),
        source,
        analysis,
        plan,
        { gen: rev2, report: quizValidator(structuredClone(rev2), [source]), attempt: 2 },
        'test-live',
        { validate: quizValidator }
      ),
      /REPAIR_BASELINE_REQUIRED/
    );
    assert.equal(requests.length, 0);
  }
  {
